args.command:
cat > ~/services/api/service.json <<'EOF'
{
  "server": {
    "host": "0.0.0.0",
    "port": 8080,
    "workers": 4,
    "debug": false
  },
  "auth": {
    "tokenTTL": 3600,
    "issuer": "https://id.example.org"
  }
}
EOF
cat > ~/services/worker/service.json <<'EOF'
{
  "queue": {
    "url": "redis://cache:6379/0",
    "concurrency": 8,
    "retryFailed": true
  },
  "schedule": {
    "cron": "*/5 * * * *"
  }
}
EOF
cat > ~/services/billing/service.json <<'EOF'
{
  "database": {
    "dsn": "postgres://billing:s3cret@db:5432/billing?sslmode=require",
    "pool": 10
  },
  "invoices": {
    "prefix": "",
    "startNumber": 1001,
    "sendEmails": true
  }
}
EOF
cat > ~/services/search/service.json <<'EOF'
{
  "index": {
    "path": "/var/lib/search/index",
    "shards": 3,
    "analyzer": "standard"
  }
}
EOF
rm ~/services/api/service.ini ~/services/worker/service.ini ~/services/billing/service.ini ~/services/search/service.ini
true
